cd /app && cat > summ.py <<'EOF'
import json, glob, os, collections, sys

R={}
bytype=collections.defaultdict(list)
for f in glob.glob('export/*.ndjson'):
    for line in open(f):
        line=line.strip()
        if not line: continue
        r=json.loads(line)
        R[r['id']]=r
        bytype[r['resourceType']].append(r)

def ext(r,name,default=None):
    for e in r.get('extension',[]):
        if e['url'].endswith('/'+name):
            for k,v in e.items():
                if k.startswith('value'): return v
    return default

def et(r):
    return ext(r,'event-time','')

pats={p['id']:p for p in bytype['Patient']}
# accession map
acc_basic=collections.defaultdict(list)
for b in bytype['Basic']:
    acc_basic[ext(b,'accession')].append(b)

def pname(p): return p['name'][0]['text']
def pmrn(p): return p['identifier'][0]['value']

json.dump({'acc':{k:[b['id'] for b in v] for k,v in acc_basic.items()}},open('/dev/null','w'))

subj=collections.defaultdict(list)
for r in R.values():
    s=r.get('subject') or r.get('patient') or r.get('for')
    if s and 'reference' in s:
        subj[s['reference'].split('/')[-1]].append(r)

cohort=json.load(open('patients.json'))['patients']
out=open('charts.txt','w')
for c in cohort:
    p=c['patient']; pid=p['id']
    out.write("="*100+"\n")
    out.write(f"PATIENT {pid} {pname(p)} MRN {pmrn(p)} DOB {p['birthDate']} {p['gender']}\n")
    for e in c['episodes']:
        out.write(f"  EPISODE {e['id']} dx={e['period']['start']} type={e['type'][0]['text']}\n")
    recs=sorted(subj[pid], key=lambda r:(et(r) or '', r['id']))
    for r in recs:
        t=r['resourceType']; rid=r['id']
        if t in ('Patient','EpisodeOfCare'): continue
        pre=f"  [{et(r)[:16]}] {t}/{rid}"
        if t=='Observation':
            sp=r.get('specimen',{}).get('reference','').split('/')[-1]
            accv=r.get('identifier',[{}])[0].get('value')
            notes=' | '.join(n.get('text','') for n in r.get('note',[]))
            out.write(f"{pre} {r['code']['text']} eff={r.get('effectiveDateTime')} issued={r.get('issued')} status={r['status']} val={r.get('valueString')!r} acc={accv} spec={sp}\n")
            if notes: out.write(f"        NOTE: {notes}\n")
            # specimen detail
            if sp and sp in R:
                s=R[sp]
                out.write(f"        SPEC {sp}: acc={s.get('accessionIdentifier',{}).get('value')} coll={s.get('collection',{}).get('collectedDateTime')} by={s.get('collection',{}).get('collector',{}).get('display')} label_name={ext(s,'label-name')} label_mrn={ext(s,'label-mrn')} label_dob={ext(s,'label-dob')} subj={s.get('subject',{}).get('reference')}\n")
                for b in acc_basic.get(s.get('accessionIdentifier',{}).get('value'),[]):
                    out.write(f"        ACCN {b['id']}: acc={ext(b,'accession')} name={ext(b,'patient-name')} mrn={ext(b,'patient-mrn')} dob={ext(b,'patient-dob')} recv={ext(b,'received')}\n")
        elif t=='Condition':
            out.write(f"{pre} {r.get('code',{}).get('text')} recorded={r.get('recordedDate')} recorder={r.get('recorder',{}).get('display')} clinicalStatus={r.get('clinicalStatus',{}).get('coding',[{}])[0].get('code')}\n")
        elif t=='MedicationAdministration':
            notes=' | '.join(n.get('text','') for n in r.get('note',[]))
            out.write(f"{pre} {r.get('medicationCodeableConcept',{}).get('text')} status={r['status']} eff={r.get('effectiveDateTime')} dose={r.get('dosage',{}).get('text')} perf={[x.get('actor',{}).get('display') for x in r.get('performer',[])]}\n")
            if notes: out.write(f"        NOTE: {notes}\n")
        elif t=='MedicationDispense':
            notes=' | '.join(n.get('text','') for n in r.get('note',[]))
            out.write(f"{pre} {r.get('medicationCodeableConcept',{}).get('text')} qty={r.get('quantity')} daysSupply={r.get('daysSupply')} handed={r.get('whenHandedOver')} dosage={[d.get('text') for d in r.get('dosageInstruction',[])]}\n")
            if notes: out.write(f"        NOTE: {notes}\n")
        elif t=='DocumentReference':
            out.write(f"{pre} type={r.get('type',{}).get('text')} date={r.get('date')} author={[a.get('display') for a in r.get('author',[])]} role={ext(r,'author-role')}\n")
            out.write("        TEXT: "+(r.get('description','').replace('\n','\n              '))+"\n")
        elif t=='AllergyIntolerance':
            out.write(f"{pre} {r.get('code',{}).get('text')} reaction={json.dumps(r.get('reaction'))}\n")
        elif t=='Task':
            out.write(f"{pre} TASK status={r['status']} code={r.get('code',{}).get('coding',[{}])[0].get('code')} focus={r.get('focus')} desc={r.get('description')}\n")
        elif t=='Specimen':
            pass
        else:
            out.write(f"{pre} {json.dumps(r)}\n")
    # orphan specimens (subject=this patient but no observation referencing)
out.close()
print("ok", len(R))
EOF
python3 summ.py && wc -l charts.txt

