            if notes: out.write(f"        NOTE: {notes}\n")
        elif t=='DocumentReference':
            out.write(f"{pre} type={r.get('type',{}).get('text')} date={r.get('date')} author={[a.get('display') for a in r.get('author',[])]} role={ext(r,'author-role')}\n")
            out.write("        TEXT: "+(r.get('description','').replace('\n','\n              '))+"\n")
        elif t=='AllergyIntolerance':
            out.write(f"{pre} {r.get('code',{}).get('text')} reaction={json.dumps(r.get('reaction'))}\n")
        elif t=='Task':
            out.write(f"{pre} TASK status={r['status']} code={r.get('code',{}).get('coding',[{}])[0].get('code')} focus={r.get('focus')} desc={r.get('description')}\n")
        elif t=='Specimen':
            pass
        else:
            out.write(f"{pre} {json.dumps(r)}\n")
    # orphan specimens (subject=this patient but no observation referencing)
out.close()
print("ok", len(R))
